import { Component, OnInit } from '@angular/core';
import { SalesService } from 'src/app/services/sales.service';

interface Sale {
  id: number;
  itemName: string;
  buyer: string;
  delivered: boolean;
  orderStatus: string;
  orderDate: Date;
  shippedDate?: Date;
  deliveredDate?: Date;
  trackingNumber?: string;
  shippingAddress?: string;
  price?: number;
}

@Component({
  selector: 'app-sales',
  templateUrl: './sales.component.html',
  styleUrls: ['./sales.component.css'],
})
export class SalesComponent implements OnInit {
  sales: Sale[] = [];
  filteredSales: Sale[] = [];
  selectedStatus = 'ALL';
  searchTerm = '';
  isLoading = true;

  // Modal properties
  showTrackingModal = false;
  showDetailsModal = false;
  selectedSale: Sale | null = null;
  trackingNumber = '';
  courierPartner = '';

  constructor(private salesService: SalesService) {}

  ngOnInit(): void {
    this.loadSales();
  }

  loadSales(): void {
    this.isLoading = true;
    this.salesService.getAllSales().subscribe({
      next: (data) => {
        this.sales = data.map((sale) => ({
          ...sale,
          orderStatus:
            sale.orderStatus || (sale.delivered ? 'DELIVERED' : 'PENDING'),
          orderDate: sale.orderDate || new Date(),
        }));
        this.filteredSales = [...this.sales];
        this.isLoading = false;
      },
      error: (err) => {
        console.error('Error loading sales:', err);
        this.isLoading = false;
        this.loadSampleData();
      },
    });
  }

  loadSampleData(): void {
    this.sales = [
      {
        id: 1001,
        itemName: 'HP Victus Laptop',
        buyer: 'john@email.com',
        delivered: false,
        orderStatus: 'PENDING',
        orderDate: new Date(),
        price: 84999,
      },
      {
        id: 1002,
        itemName: 'Samsung Galaxy A36',
        buyer: 'jane@email.com',
        delivered: false,
        orderStatus: 'SHIPPED',
        orderDate: new Date(),
        price: 33999,
        shippedDate: new Date(),
        trackingNumber: 'DTDC123456',
      },
      {
        id: 1003,
        itemName: 'SONY Bravia TV',
        buyer: 'mike@email.com',
        delivered: true,
        orderStatus: 'DELIVERED',
        orderDate: new Date(),
        price: 75000,
        shippedDate: new Date(),
        deliveredDate: new Date(),
      },
    ];
    this.filteredSales = [...this.sales];
  }

  filterByStatus(status: string): void {
    this.selectedStatus = status;
    this.applyFilters();
  }

  filterSales(): void {
    this.applyFilters();
  }

  applyFilters(): void {
    let filtered = [...this.sales];

    // Filter by status
    if (this.selectedStatus !== 'ALL') {
      filtered = filtered.filter(
        (sale) => sale.orderStatus === this.selectedStatus,
      );
    }

    // Filter by search term
    if (this.searchTerm) {
      const term = this.searchTerm.toLowerCase();
      filtered = filtered.filter(
        (sale) =>
          sale.id.toString().includes(term) ||
          sale.itemName.toLowerCase().includes(term) ||
          sale.buyer.toLowerCase().includes(term),
      );
    }

    this.filteredSales = filtered;
  }

  updateStatus(orderId: number, status: string): void {
    const confirmMessage =
      status === 'SHIPPED'
        ? 'Mark this order as Shipped?'
        : status === 'DELIVERED'
          ? 'Mark this order as Delivered?'
          : 'Cancel this order?';

    if (confirm(confirmMessage)) {
      this.salesService.updateOrderStatus(orderId, status).subscribe({
        next: (updatedSale) => {
          const index = this.sales.findIndex((s) => s.id === orderId);
          if (index !== -1) {
            this.sales[index] = updatedSale;
            this.applyFilters();
          }
          alert(
            `Order ${status === 'SHIPPED' ? 'shipped' : status === 'DELIVERED' ? 'delivered' : 'cancelled'} successfully!`,
          );
        },
        error: (err) => {
          console.error('Error updating status:', err);
          alert('Failed to update order status');
        },
      });
    }
  }

  addTrackingNumber(sale: Sale): void {
    this.selectedSale = sale;
    this.trackingNumber = '';
    this.courierPartner = '';
    this.showTrackingModal = true;
  }

  saveTrackingNumber(): void {
    if (!this.trackingNumber) {
      alert('Please enter a tracking number');
      return;
    }

    const fullTracking = this.courierPartner
      ? `${this.courierPartner}: ${this.trackingNumber}`
      : this.trackingNumber;

    this.salesService
      .addTrackingNumber(this.selectedSale!.id, fullTracking)
      .subscribe({
        next: (updatedSale) => {
          const index = this.sales.findIndex(
            (s) => s.id === this.selectedSale!.id,
          );
          if (index !== -1) {
            this.sales[index] = updatedSale;
            this.applyFilters();
          }
          this.closeTrackingModal();
          alert('Tracking number added successfully!');
        },
        error: (err) => {
          console.error('Error adding tracking:', err);
          alert('Failed to add tracking number');
        },
      });
  }

  viewOrderDetails(sale: Sale): void {
    this.selectedSale = sale;
    this.showDetailsModal = true;
  }

  closeTrackingModal(): void {
    this.showTrackingModal = false;
    this.selectedSale = null;
    this.trackingNumber = '';
    this.courierPartner = '';
  }

  closeDetailsModal(): void {
    this.showDetailsModal = false;
    this.selectedSale = null;
  }

  getStatusClass(status: string): string {
    switch (status) {
      case 'PENDING':
        return 'status-pending';
      case 'SHIPPED':
        return 'status-shipped';
      case 'DELIVERED':
        return 'status-delivered';
      case 'CANCELLED':
        return 'status-cancelled';
      default:
        return '';
    }
  }

  getStatusText(status: string): string {
    switch (status) {
      case 'PENDING':
        return '⏳ Pending';
      case 'SHIPPED':
        return '🚚 Shipped';
      case 'DELIVERED':
        return '✅ Delivered';
      case 'CANCELLED':
        return '❌ Cancelled';
      default:
        return 'Unknown';
    }
  }

  formatPrice(price: number): string {
    return price?.toLocaleString('en-IN') || '0';
  }
}
